<details>
<summary>Code</summary>

```jsx
// MyComponent.tsx
function MyComponent({ content }: { content: JSX.Element | string }) {
  return <div>{content}</div>;
}

export default MyComponent;

// MyComponent.test.tsx
import { expect, test } from '@playwright/experimental-ct-react';
import MyComponent from './MyComponent';

// Succeeds
test('renders a string prop', async ({ mount }) => {
  const component = await mount(<MyComponent content="Howdy" />);

  await expect(component).toContainText('Howdy');
});

const inner = () => <div>Howdy</div>;

// Fails
test('renders the result of a function', async ({ mount }) => {
  const component = await mount(<MyComponent content={inner()} />);

  await expect(component).toContainText('Howdy');
});

// Fails
test('renders a jsx prop', async ({ mount }) => {
  const component = await mount(<MyComponent content={<div>Howdy</div>} />);

  await expect(component).toContainText('Howdy');
});
```
